for i,row in enumerate(R,1):
    row["row_id"]=f"BM{i:03d}"; row["class"]=P; row.setdefault("include_v1","yes")
with open("literature_call_parameters_blue.csv","w",newline="",encoding="utf-8") as f:
    w=csv.DictWriter(f,fieldnames=cols); w.writeheader()
    for row in R: w.writerow({c:row.get(c,"") for c in cols})
print(len(R),"rows")
